public function recordPayment(string $tenantId, string $amount, string $method, ?string $idempotencyKey = null): Payment
{
    return DB::transaction(function () use (...) {
        if ($idempotencyKey) {
            $existing = Payment::where('idempotency_key', $idempotencyKey)->first();
            if ($existing) return $existing; // Idempotent — safe to retry
        }
        $payment = Payment::create([...]);
        $this->eventStore->append($tenantId, 'payment', $payment->id, 'payment.received', ['amount' => $amount]);
        return $payment;
    });
}
