```php
public function checkBudgetLimit(string $tenantId, string $budgetId, float $amount): array
{
    $budget = Budget::findOrFail($budgetId);
    $utilization = (($budget->spent + $amount) / $budget->amount) * 100;
    if ($utilization >= 100) {
        $this->createAlert($tenantId, 'budget_exceeded', 'critical', ...);
        return ['allowed' => false, 'reason' => 'Budget exceeded'];
    }
    if ($utilization >= $budget->alert_threshold) {
        $this->createAlert($tenantId, 'budget_warning', 'warning', ...);
    }
    return ['allowed' => true, 'utilization' => $utilization];
}
```

**Fraud risk scoring:**
```php
public function detectFraudulentTransaction(string $tenantId, string $txnId, float $amount, string $method, ?string $email = null): array
{
    $risk = 0; $flags = [];
    if ($amount > 10000) { $risk += 20; $flags[] = 'large_amount'; }
    if ($email && Transaction::where('counterparty_email', $email)->count() === 0 && $amount > 1000) { $risk += 30; $flags[] = 'new_counterparty'; }
    if (Transaction::where('created_at', '>=', now()->subMinutes(30))->count() > 5) { $risk += 25; $flags[] = 'high_frequency'; }
    if ((int)now()->format('H') >= 2 && (int)now()->format('H') <= 5) { $risk += 15; $flags[] = 'unusual_hour'; }
    if ($risk >= 50) { $this->createAlert($tenantId, 'fraud_suspected', 'critical', ...); }
    return ['risk_score' => $risk, 'status' => $risk >= 50 ? 'flagged' : 'approved', 'flags' => $flags];
}
```

Flags trigger FinancialAlert entries visible in the dashboard. Score >= 50 requires human approval.

**PortfolioService** (`backend/app/Services/Financial/PortfolioService.php`):

```php
public function addPosition(string $portfolioId, string $tenantId, string $assetType, string $symbol, string $qty, string $price): PortfolioPosition
{
    $existing = PortfolioPosition::where('portfolio_id', $portfolioId)->where('symbol', $symbol)->first();
    if ($existing) {
        // Average cost: (old_cost * old_qty + new_price * new_qty) / total_qty
        $totalQty = $existing->quantity + $qty;
        $existing->quantity = $totalQty;
        $existing->avg_cost = (($existing->avg_cost * $existing->quantity) + ($price * $qty)) / $totalQty;
        $existing->save();
        return $existing;
    }
    return PortfolioPosition::create([...]);
}

public function executeTrade(string $portfolioId, string $tenantId, string $assetType, string $symbol, string $side, string $qty, string $price): Trade
{
    return DB::transaction(function () use (...) {
        $trade = Trade::create([...]);
        if ($side === 'buy') $this->addPosition(...);
        else { $pos = PortfolioPosition::where(...)->first(); $pos->quantity -= $qty; $pos->quantity <= 0 ? $pos->delete() : $pos->save(); }
        $this->eventStore->append($tenantId, 'trade', $trade->id, 'trade.executed', [...]);
        return $trade;
    });
}
```

