5 controllers in `backend/app/Http/Controllers/Financial/`. Pattern:

```php
<?php
namespace App\Http\Controllers\Financial;

use App\Http\Controllers\Controller;
use App\Services\Financial\LedgerService;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;

class LedgerController extends Controller
{
    public function __construct(private readonly LedgerService $ledgerService) {}

    public function index(Request $request): JsonResponse
    {
        $tenant = $request->attributes->get('tenant');
        $entries = LedgerEntry::forTenant($tenant->id)->with('account')->orderByDesc('posted_at')->paginate($request->get('per_page', 20));
        return response()->json(['data' => $entries]);
    }

    public function journalEntry(Request $request): JsonResponse
    {
        $tenant = $request->attributes->get('tenant');
        $validated = $request->validate([
            'source_account_id' => 'required|uuid|exists:financial_accounts,id',
            'destination_account_id' => 'required|uuid|exists:financial_accounts,id',
            'amount' => 'required|numeric|min:0.01',
        ]);
        $tx = $this->ledgerService->createJournalEntry($tenant->id, $validated['source_account_id'], $validated['destination_account_id'], $validated['amount']);
        return response()->json(['data' => $tx], 201);
    }
}
```

**Rules:** Constructor injection of services, `$request->attributes->get('tenant')` for tenant scope, validate before calling service, return `['data' => ...]` format, paginate lists, 201 for creates.

